from .common import *
from .lg import S

CCl2 = "[Cl:3][C:1][Cl:4]"


def build(B):
    B.part("Part 10", "Carbenes: Structure, Generation, Singlet and Triplet States, Reactions")
    B.p("A <b>carbene</b> is a neutral species containing a divalent carbon atom with only six valence electrons: R<sub>2</sub>C: (two bonds + two non-bonding electrons). "
        "It is a Lewis acid (empty orbital) and a Lewis base (lone pair) at the same atom, and is therefore ambiphilic; most simple carbenes behave as <b>electrophiles</b> because the empty orbital dominates. "
        "Carbenes are reaction intermediates of very short lifetime (CH<sub>2</sub>: ≈ 10<sup>−9</sup> s in solution) except for stabilised cases (N-heterocyclic carbenes, Arduengo 1991).")
    B.h2("10.1  Singlet and triplet carbenes")
    B.table(["Property", "Singlet carbene", "Triplet carbene"],
        [["Electrons in the two non-bonding orbitals", "both in one orbital (σ lone pair, spin-paired); the p orbital is empty", "one electron in each of two orbitals (σ and p), spins parallel (↑↑)"],
         ["Spin multiplicity 2S + 1", "1 (S = 0)", "3 (S = 1)"],
         ["Hybridisation / shape", "sp<sup>2</sup>, <b>bent</b>; H–C–H ≈ 102–103° for CH<sub>2</sub>", "sp (linear, 180°) or sp<sup>2</sup> bent with a wider angle; H–C–H ≈ 130–136° for CH<sub>2</sub> (ground state, <sup>3</sup>B<sub>1</sub>)"],
         ["Magnetic behaviour", "diamagnetic", "paramagnetic (two unpaired electrons; ESR active)"],
         ["Character", "like a carbocation (empty p) and a carbanion (lone pair): ambiphilic, concerted reactions", "like a diradical: stepwise radical reactions"],
         ["Addition to a C=C", "<b>stereospecific, syn</b> (concerted, one step): cis-alkene → cis-cyclopropane; trans → trans", "<b>not stereospecific</b> (stepwise through a 1,3-diradical that can rotate): cis and trans mixture"],
         ["C–H insertion", "concerted, with retention of configuration at the carbon that is attacked", "H-abstraction then radical recombination (loss of stereochemistry)"],
         ["Examples", ":CCl<sub>2</sub>, :CF<sub>2</sub>, :CBr<sub>2</sub>, :C(OR)<sub>2</sub>, :C(NR<sub>2</sub>)<sub>2</sub>, Arduengo carbene, the carbenoids; CH<sub>2</sub> generated by photolysis of CH<sub>2</sub>N<sub>2</sub> in solution (first singlet)", "ground-state :CH<sub>2</sub> (triplet is ≈ 9 kcal mol<sup>−1</sup> lower), :CHPh, :CPh<sub>2</sub> (diarylcarbenes), :C: (C atom has a triplet ground state)"]],
        widths=[22, 39, 39])
    B.p("<b>What decides the spin state?</b> A singlet is favoured when the substituents are <b>π-donors</b> (X–: F, Cl, Br, OR, NR<sub>2</sub>) because their lone pair donates into the empty p orbital (stabilising the singlet by delocalisation, 2p–2p overlap best for F, N, O) and σ-withdrawing groups lower the energy of the σ orbital (more s-character in the lone pair). "
        "A triplet is favoured by substituents that are π-conjugating without lone pairs (aryl groups: Ph<sub>2</sub>C: is a triplet) or sterically demanding groups that widen the angle, and by σ-donors. "
        "The 1,2-shift reactions (Wolff, hydride) that occur at carbenes are almost always singlet processes.")
    B.warn("<b>Stability order of dihalocarbenes (singlet):</b> :CF<sub>2</sub> &gt; :CCl<sub>2</sub> &gt; :CBr<sub>2</sub> &gt; :CI<sub>2</sub> by π-back-donation of the 2p lone pair of F into the empty p orbital of carbon (effective 2p–2p overlap); Cl, Br, I overlap poorly (3p, 4p, 5p with 2p). "
           "⚑ Do not confuse with the <i>electrophilicity</i>/ease of formation: :CCl<sub>2</sub> forms most easily from CHCl<sub>3</sub> because Cl<sup>−</sup> is a better leaving group and the CCl<sub>3</sub><sup>−</sup> anion is more stable than CF<sub>3</sub><sup>−</sup>.")
    B.h2("10.2  Generation of carbenes")
    B.table(["Method", "Equation", "Comment"],
        [["α-Elimination of HX from a haloform", "CHCl<sub>3</sub> + KOH → <sup>−</sup>CCl<sub>3</sub> + H<sub>2</sub>O → :CCl<sub>2</sub> + Cl<sup>−</sup>", "carbanion first, then loss of halide; the basis of Reimer–Tiemann, carbylamine and dichlorocyclopropane formation"],
         ["Photolysis/thermolysis of diazomethane (diazo compounds)", "CH<sub>2</sub>N<sub>2</sub> → :CH<sub>2</sub> + N<sub>2</sub>;  R<sub>2</sub>C=N<sub>2</sub> → R<sub>2</sub>C: + N<sub>2</sub>", "the irreversible loss of the superb leaving group N<sub>2</sub>; singlet first, then triplet by collisions"],
         ["Photolysis of ketene", "CH<sub>2</sub>=C=O → :CH<sub>2</sub> + CO", "gas phase source of methylene"],
         ["Tosylhydrazone salts (Bamford–Stevens/Shapiro)", "R<sub>2</sub>C=N–NH–Ts + base → R<sub>2</sub>C=N–N<sup>−</sup>–Ts → R<sub>2</sub>C: + N<sub>2</sub> + Ts<sup>−</sup>", "diazo compound is formed in situ"],
         ["Simmons–Smith carbenoid", "CH<sub>2</sub>I<sub>2</sub> + Zn(Cu) → I–CH<sub>2</sub>–ZnI", "not a free carbene (carbenoid): CH<sub>2</sub> is transferred to alkenes in a concerted way; stereospecific, OH-directed"],
         ["Diazirines, epoxides (deoxygenation), metal-carbene complexes", "diazirine → carbene + N<sub>2</sub>", "photolabelling"],
         ["Wolff rearrangement precursor", "R–CO–CHN<sub>2</sub> → R–CO–CH: + N<sub>2</sub> → R–CH=C=O (ketene)", "Arndt–Eistert homologation"]],
        widths=[26, 44, 30])
    B.h2("10.3  Reactions of carbenes")
    B.table(["Reaction", "Example", "Outcome"],
        [["Cyclopropanation of alkenes", ":CCl<sub>2</sub> + cyclohexene → 7,7-dichlorobicyclo[4.1.0]heptane; CH<sub>2</sub>I<sub>2</sub>/Zn–Cu + alkene", "syn addition; carbene is electrophilic so electron-rich alkenes react faster (Me<sub>2</sub>C=CMe<sub>2</sub> &gt; Me<sub>2</sub>C=CH<sub>2</sub> &gt; CH<sub>2</sub>=CH<sub>2</sub> &gt; CH<sub>2</sub>=CH–CN)"],
         ["C–H insertion", ":CH<sub>2</sub> + CH<sub>3</sub>CH<sub>3</sub> → CH<sub>3</sub>CH<sub>2</sub>CH<sub>3</sub>", "indiscriminate (carbene is so reactive it inserts into primary, secondary, tertiary C–H nearly statistically)"],
         ["Reimer–Tiemann", "PhOH + CHCl<sub>3</sub> + NaOH → salicylaldehyde (major, ortho) + p-hydroxybenzaldehyde (minor)", "phenoxide attacks :CCl<sub>2</sub> through the ortho carbon (chelation by Na<sup>+</sup>), then hydrolysis of ArCHCl<sub>2</sub> to ArCHO. With CCl<sub>4</sub> in place of CHCl<sub>3</sub> the product is salicylic acid"],
         ["Carbylamine (Hofmann isocyanide) test", "RNH<sub>2</sub> + CHCl<sub>3</sub> + 3 KOH → R–N≡C + 3 KCl + 3 H<sub>2</sub>O", "primary amines only (aliphatic or aromatic); isocyanide has an offensive smell (the test). Secondary and tertiary amines do not react"],
         ["Wolff rearrangement", "ArCOCHN<sub>2</sub> → [ArCO–CH:] → Ar–CH=C=O", "1,2-aryl/alkyl shift to the carbene carbon gives a ketene; trapping with H<sub>2</sub>O gives ArCH<sub>2</sub>COOH (Arndt–Eistert)"],
         ["Ring expansion (Ciamician–Dennstedt)", "pyrrole + :CCl<sub>2</sub> → 3-chloropyridine", "dihalocyclopropane intermediate opens with ring expansion"],
         ["Buchner reaction", "benzene + :CHCO<sub>2</sub>Et (from N<sub>2</sub>CHCO<sub>2</sub>Et) → cycloheptatriene ester", "addition to benzene then electrocyclic ring opening"],
         ["Dimerisation", "2 :CPh<sub>2</sub> → Ph<sub>2</sub>C=CPh<sub>2</sub>", "triplet carbenes in the absence of traps"],
         ["Reaction with Lewis bases (ylide formation)", ":CH<sub>2</sub> + R<sub>3</sub>N, R<sub>2</sub>S, Ph<sub>3</sub>P → ylides", "the lone-pair donor attacks the empty p orbital"]],
        widths=[22, 42, 36])
    B.h2("10.4  Mechanisms (arrow-validated)")
    c = []
    c.append(ex("10.1", "Diazomethane → methylene + N<sub>2</sub>",
        "[CH2-:1][N+:2]#[N:3]",
        [St(A(('b', 1, 2), ('lp', 2), 0.5), "hν or Δ", expect="[CH2].N#N")],
        "[CH2].N#N",
        "The C–N σ pair leaves with N<sub>2</sub>; the carbanion lone pair that was on carbon becomes the lone pair of the carbene. The product is first a singlet methylene (lone pair + empty p), which decays to the triplet ground state."))
    c.append(ex("10.2", "α-Elimination: chloroform + HO<sup>−</sup> → :CCl<sub>2</sub>",
        "[C:1]([H:2])([Cl:3])([Cl:4])[Cl:5]",
        [St([A(('lp', 90), ('nb', 90, 2), 0.5), A(('b', 1, 2), ('lp', 1), -0.5)], "HO^−", add="[OH-:90]", carbanions=[1], expect="ClC(Cl)(Cl)[C-]".replace("ClC(Cl)(Cl)[C-]", "Cl[C-](Cl)Cl") + ".O"),
         St(A(('b', 1, 5), ('lp', 5), 0.5), "−Cl^−", expect="Cl[C]Cl.O.[Cl-]")],
        "Cl[C]Cl.O.[Cl-]",
        "Hydroxide removes the single proton of CHCl<sub>3</sub> (pK<sub>a</sub> ≈ 24) to give <sup>−</sup>CCl<sub>3</sub>; the carbanion expels chloride from the same carbon (α-elimination) to give dichlorocarbene. The lone pair on carbon is the carbene lone pair; the empty p orbital is the electrophilic site."))
    c.append(ex("10.3", "Dichlorocarbene + cyclohexene: concerted syn-cyclopropanation (singlet)",
        CCl2 + ".[CH:6]1=[CH:7][CH2:8][CH2:9][CH2:10][CH2:11]1",
        [St([A(('b', 6, 7), ('nb', 6, 1), 0.5), A(('lp', 1), ('nb', 1, 7), -0.5)], "one step", expect="ClC1(Cl)C2CCCCC12")],
        "ClC1(Cl)C2CCCCC12",
        "The alkene π electrons attack the empty p orbital of the carbene while the carbene lone pair forms the second C–C bond: both bonds form simultaneously on the same face of the alkene, so the stereochemistry of the alkene is retained (stereospecific syn addition). The product is 7,7-dichlorobicyclo[4.1.0]heptane (a <i>cis</i>-fused, achiral meso compound)."))
    c.append(ex("10.4", "Carbene C–H insertion: :CH<sub>2</sub> + ethane → propane",
        "[CH2:1].[CH3:4][CH2:2][H:3]",
        [St([A(('b', 2, 3), ('nb', 1, 2), 0.5), A(('lp', 1), ('nb', 1, 3), -0.5)], "three-centre TS", expect="CCC")],
        "CCC",
        "In the singlet insertion the C–H σ electrons attack the empty p orbital of the carbene while the carbene lone pair accepts the hydrogen: a single three-centre transition state with retention at the attacked carbon. Triplet carbenes insert by abstraction–recombination, which loses stereochemistry."))
    c.append(ex("10.5", "Wolff rearrangement: α-diazoketone → ketene",
        "[CH3:1][C:2](=[O:3])[CH-:4][N+:5]#[N:6]",
        [St(A(('b', 4, 5), ('lp', 5), 0.5), "hν or Ag_2O, −N_2", carbanions=[], expect="CC(=O)[CH].N#N"),
         St([A(('b', 1, 2), ('nb', 1, 4), 0.5), A(('lp', 4), ('nb', 4, 2), -0.5)], "1,2-CH_3 shift", expect="CC=C=O.N#N")],
        "CC=C=O.N#N",
        "Loss of N<sub>2</sub> gives an α-ketocarbene; the substituent on the carbonyl carbon migrates with its bonding pair to the electron-deficient carbene carbon while the carbene lone pair forms the C=C of the ketene (the migrating group moves to the carbon that was the carbene). Water traps the ketene as the carboxylic acid with one more carbon (Arndt–Eistert chain extension): R–COCl → R–CO–CHN<sub>2</sub> → R–CH<sub>2</sub>COOH.", width=680))
    c.append(ex("10.6", "Simmons–Smith: iodomethylzinc iodide + cyclohexene → norcarane",
        "[I:1][CH2:2][Zn:3][I:4].[CH:5]1=[CH:6][CH2:7][CH2:8][CH2:9][CH2:10]1",
        [St([A(('b', 5, 6), ('nb', 5, 2), 0.5), A(('b', 2, 3), ('nb', 2, 6), -0.5), A(('b', 2, 1), ('lp', 1), 0.5)], "butterfly TS", expect="C1CC2CC2CC1.[I-].[Zn+]I")],
        "C1CC2CC2CC1.[I-].[Zn+]I",
        "The carbenoid is not a free carbene: the CH<sub>2</sub> is delivered, with simultaneous loss of iodide, from the carbon bound to zinc to both alkene carbons in a three-centre ‘butterfly’ transition state. The addition is stereospecific syn and is accelerated by an allylic OH group that coordinates zinc (the directing effect), which free :CH<sub>2</sub> would not show."))
    B.grid(c, 2)
    B.h2("10.5  The Reimer–Tiemann and carbylamine reactions in detail")
    c = []
    c.append(ex("10.7", "Reimer–Tiemann: phenoxide attacks dichlorocarbene at the ortho carbon",
        "[O-:1][C:2]1=[C:3]([H:30])[CH:4]=[CH:5][CH:6]=[CH:7]1.[Cl:20][C:21][Cl:22]",
        [St([A(('lp', 1), ('nb', 1, 2), 0.5), A(('b', 2, 3), ('nb', 3, 21), 0.5)], "ortho attack", carbanions=[21], expect="O=C1C=CC=CC1[C-](Cl)Cl"),
         St([A(('lp', 21), ('nb', 21, 30), 0.5), A(('b', 3, 30), ('nb', 3, 2), -0.5), A(('b', 1, 2), ('lp', 1), 0.5)], "H shift, re-aromatisation", expect="[O-]c1ccccc1C(Cl)Cl")],
        "[O-]c1ccccc1C(Cl)Cl",
        "The phenoxide ring is the nucleophile (the negative charge is shared with the ortho and para carbons). It attacks :CCl<sub>2</sub>; the resulting dienone carbanion regains aromaticity by a proton shift to give the o-(dichloromethyl)phenoxide. Hydroxide then hydrolyses the benzal chloride (ArCHCl<sub>2</sub>) twice to ArCH(OH)<sub>2</sub> → ArCHO. The ortho product predominates because Na<sup>+</sup> chelates phenoxide O and the carbene; the para isomer is the minor product.", width=680))
    c.append(ex("10.8", "Carbylamine reaction, first step: primary amine + dichlorocarbene",
        "[CH3:1][NH2:2]." + "[Cl:3][C:4][Cl:5]",
        [St(A(('lp', 2), ('nb', 2, 4), 0.5), "", carbanions=[4], expect="C[NH2+][C-](Cl)Cl")],
        None,
        "The nitrogen lone pair attacks the empty p orbital of the carbene to give a zwitterion (ammonium/carbanion). Two successive deprotonation–dechlorination steps (base removes N–H, Cl<sup>−</sup> leaves) then convert R–NH<sub>2</sub><sup>+</sup>–CCl<sub>2</sub><sup>−</sup> into R–N<sup>+</sup>≡C<sup>−</sup>, the isocyanide: the isocyanide carbon is itself a carbene-like divalent carbon (R–N<sup>+</sup>≡C<sup>−</sup> ↔ R–N=C:)."))
    B.grid(c, 2)
    from . import carbene_adv as adv
    adv.theory(B)
    B.h2("10.13  Additional validated mechanisms")
    adv.mechanisms(B)
    B.h2("10.14  Problems on carbenes")
    qs = []
    def q(n, text, fig, ans, why):
        qs.append(Q(f"CE-{n}", text, fig, ans, why))
    q(1, "How many valence electrons does the carbon atom of a carbene have, and how many are non-bonding?",
      None, "6; 2 non-bonding", "Two electrons in each of the two σ bonds, plus two non-bonding electrons (a lone pair in the singlet; two unpaired electrons in the triplet) = 6 around carbon, an incomplete octet.")
    q(2, "Which statements about singlet methylene are correct? (A) sp<sup>2</sup>, bent, H–C–H ≈ 103°; (B) paramagnetic; (C) shows stereospecific syn addition to alkenes; (D) has an empty p orbital.",
      None, "(A), (C), (D)", "Singlet CH<sub>2</sub> has a filled sp<sup>2</sup> lone pair and an empty p orbital; it is diamagnetic (all electrons paired). Triplet methylene is paramagnetic with H–C–H ≈ 136°.")
    q(3, "The addition of singlet :CBr<sub>2</sub> to cis-but-2-ene gives how many products, and what are they? What happens with a triplet carbene?",
      S([("", "C/C=C\\C")]), "singlet: one (cis-1,1-dibromo-2,3-dimethylcyclopropane, meso); triplet: two (cis and trans)", "Concerted syn addition retains the cis relationship of the two methyl groups, giving the achiral meso cyclopropane. A triplet carbene adds stepwise through a 1,3-diradical that can rotate before the second bond closes, giving cis and trans (the trans is chiral, as a racemate).")
    q(4, "Phenol is heated with CHCl<sub>3</sub> and aqueous NaOH, and then acidified. Name the major and minor organic products and the electrophile.",
      S([("major", "O=Cc1ccccc1O"), ("minor", "O=Cc1ccc(O)cc1")]), "salicylaldehyde (major) and p-hydroxybenzaldehyde (minor); electrophile :CCl<sub>2</sub>", "Hydroxide converts CHCl<sub>3</sub> into :CCl<sub>2</sub> (electrophilic carbene) and phenol into phenoxide (activated ring). Ortho attack is favoured by Na<sup>+</sup> chelation. Replace CHCl<sub>3</sub> by CCl<sub>4</sub> and the product is salicylic acid.")
    q(5, "Which of the following give a positive carbylamine test? (a) CH<sub>3</sub>NH<sub>2</sub>, (b) (CH<sub>3</sub>)<sub>2</sub>NH, (c) C<sub>6</sub>H<sub>5</sub>NH<sub>2</sub>, (d) (CH<sub>3</sub>)<sub>3</sub>N, (e) CH<sub>3</sub>CONH<sub>2</sub>, (f) C<sub>6</sub>H<sub>5</sub>NHCH<sub>3</sub>.",
      None, "(a) and (c)", "The sequence R–NH<sub>2</sub> + :CCl<sub>2</sub> → R–N<sup>+</sup>≡C<sup>−</sup> needs two N–H bonds that can both be lost. Secondary (b, f) and tertiary (d) amines lack them and amides (e) are not nucleophilic enough.")
    q(6, "Arrange in decreasing stability: :CF<sub>2</sub>, :CCl<sub>2</sub>, :CBr<sub>2</sub>, :CI<sub>2</sub>.",
      None, ":CF<sub>2</sub> &gt; :CCl<sub>2</sub> &gt; :CBr<sub>2</sub> &gt; :CI<sub>2</sub>", "π back-donation from the halogen lone pair into the empty carbon p orbital is best for the 2p orbital of fluorine (similar size and energy); it decreases as the halogen orbital becomes larger and more diffuse. (Part 5D, problem D-38, statement vi.)")
    q(7, "Name the carbene (or carbenoid) and the product when cyclohexene reacts with (a) CH<sub>2</sub>I<sub>2</sub> + Zn–Cu, (b) CHBr<sub>3</sub> + KOtBu, (c) CH<sub>2</sub>N<sub>2</sub> + hν.",
      None, "(a) ICH<sub>2</sub>ZnI (carbenoid) → norcarane; (b) :CBr<sub>2</sub> → 7,7-dibromonorcarane; (c) :CH<sub>2</sub> → norcarane (plus C–H insertion products)", "Each adds one carbon across the double bond to give a bicyclo[4.1.0]heptane. Free :CH<sub>2</sub> from diazomethane also inserts into C–H bonds and gives a mixture (low selectivity); the Simmons–Smith carbenoid is the clean method.")
    q(8, "What is the product of the Arndt–Eistert sequence starting from CH<sub>3</sub>COOH? (i) SOCl<sub>2</sub>; (ii) CH<sub>2</sub>N<sub>2</sub>; (iii) Ag<sub>2</sub>O, H<sub>2</sub>O.",
      None, "propanoic acid, CH<sub>3</sub>CH<sub>2</sub>COOH", "CH<sub>3</sub>COCl + CH<sub>2</sub>N<sub>2</sub> → CH<sub>3</sub>COCHN<sub>2</sub>; Ag<sub>2</sub>O gives the carbene, Wolff shift gives CH<sub>3</sub>CH=C=O (methylketene), water gives CH<sub>3</sub>CH<sub>2</sub>COOH: homologation by one CH<sub>2</sub>.")
    q(9, "Which of the following is not a method of generating a carbene? (A) CHCl<sub>3</sub> + KOH, (B) CH<sub>2</sub>N<sub>2</sub> + hν, (C) CH<sub>2</sub>=C=O + hν, (D) CH<sub>3</sub>Cl + AlCl<sub>3</sub>.",
      None, "(D)", "CH<sub>3</sub>Cl + AlCl<sub>3</sub> gives CH<sub>3</sub><sup>+</sup> (a carbocation, Friedel–Crafts), not a carbene.")
    q(10, "Hydrolysis of CHCl<sub>3</sub> with aqueous alkali would be expected to give HCOOH via :CCl<sub>2</sub>. Write the intermediate sequence.",
      None, "CHCl<sub>3</sub> → CCl<sub>3</sub><sup>−</sup> → :CCl<sub>2</sub> → HCCl(OH)… → HCOO<sup>−</sup>", "Hydroxide removes the proton (carbanion), Cl<sup>−</sup> is lost (carbene), the carbene is attacked by HO<sup>−</sup> and the resulting dichlorohydrin/formyl species loses two Cl<sup>−</sup> to give formate (or CO + HCl). This is the same carbene that does the Reimer–Tiemann reaction.")
    q(11, "Why is the triplet the ground state of methylene while the singlet is the ground state of :CF<sub>2</sub>?",
      None, "π-donation and electronegativity", "In CH<sub>2</sub> the two non-bonding orbitals (σ and p) are close in energy (≈ 9 kcal mol<sup>−1</sup>), so Hund’s rule puts one electron in each. In :CF<sub>2</sub> the fluorine lone pairs donate into the empty p orbital and raise its energy, while the σ-withdrawing F lowers the energy of the σ orbital: the gap widens (≈ 56 kcal mol<sup>−1</sup>) and the singlet becomes the ground state.")
    q(12, "A stable, crystalline carbene is made from an imidazolium salt and a base. Which features make it stable?",
      S([("", "CC(C)c1cccc(C(C)C)c1N1C=CN(c2c(C(C)C)cccc2C(C)C)[C]1")]), "two π-donating N atoms and bulky N-substituents", "The two nitrogen lone pairs donate into the empty p orbital (singlet stabilised, amidine-like resonance) and the σ-withdrawing N atoms lower the σ lone pair energy; the large aryl groups prevent dimerisation to the tetraaminoethylene. Arduengo (1991).")
    adv.problems(B, q)
    B.answers(qs, with_stem=True)
    return qs
